(7120, '၂-၁၂၈၆၇', '300', '၃၄၈.၅၉၁လှ', 'လှတင်ဦး(လှသမိန်)', 'မြန်မာမင်းအုပ်ချုပ်ပုံစာတမ်း နှင့် ဘိုးတော်ဘုရား၏ရာဇသတ်ခေါ်သောအမိန့်တော်ကြီး(ဒုတိယပိုင်း)', NULL, NULL, 'ရန်ကုန်', '1988', 0, '300'),
(7121, '၂-၁၂၈၆၈', '300', '၃၄၈.၅၉၁လှ', 'လှတင်ဦး(လှသမိန်)', 'မြန်မာမင်းအုပ်ချုပ်ပုံစာတမ်း နှင့် ဘိုးတော်ဘုရား၏ရာဇသတ်ခေါ်သောအမိန့်တော်ကြီး(ဒုတိယပိုင်း)', NULL, NULL, 'ရန်ကုန်', '1988', 1, '300');
